<template>
  <view class="home-container">
    <!-- 顶部轮播图 -->
    <swiper class="swiper" indicator-dots autoplay circular interval="3000" v-if="banners.length > 0">
      <swiper-item v-for="(item, index) in banners" :key="index">
        <image :src="item.image_url" mode="aspectFill" class="swiper-image" @click="navigateToDetail(item)"></image>
      </swiper-item>
    </swiper>

    <!-- 搜索框 -->
    <view class="search-bar">
      <input class="search-input" placeholder="搜索景点、店铺或美食" @click="navigateToSearch" :value="searchKeyword"
        @input="onSearchInput" confirm-type="search" @confirm="onSearchConfirm" />
      <uni-icons type="search" size="20" color="#00B4D8" @click="onSearchConfirm"></uni-icons>
    </view>

    <!-- 功能入口 -->
    <view class="function-grid">
      <view class="function-item" @tap="navigateToQA">
        <view class="function-icon" style="background-color: #FF6B6B;">
          <uni-icons type="help" size="24" color="#fff"></uni-icons>
        </view>
        <text class="function-text">智能问答</text>
      </view>
      <view class="function-item" @tap="navigateToMap">
        <view class="function-icon" style="background-color: #4ECDC4;">
          <uni-icons type="location" size="24" color="#fff"></uni-icons>
        </view>
        <text class="function-text">地图导航</text>
      </view>
      <view class="function-item" @tap="navigateToCommunity">
        <view class="function-icon" style="background-color: #45B7D1;">
          <uni-icons type="person" size="24" color="#fff"></uni-icons>
        </view>
        <text class="function-text">社区互动</text>
      </view>
      <view class="function-item" @tap="navigateToFood">
        <view class="function-icon" style="background-color: #FFA5A5;">
          <uni-icons type="shop" size="24" color="#fff"></uni-icons>
        </view>
        <text class="function-text">景德镇美食</text>
      </view>
    </view>

    <!-- 景点推荐 -->
    <view class="section" v-if="spots.length > 0">
      <view class="section-header">
        <text class="section-title">热门景点</text>
        <text class="section-more" @click="navigateToSpotList">查看更多 ></text>
      </view>
      <scroll-view class="scroll-view" scroll-x>
        <view class="spot-item" v-for="(spot, index) in spots" :key="index" @click="navigateToSpotDetail(spot.spot_id)">
          <image :src="getMainImage(spot.spot_id, 'spot')" mode="aspectFill" class="spot-image"></image>
          <view class="spot-info">
            <text class="spot-name">{{spot.spot_name}}</text>
            <view class="spot-rating">
              <uni-icons type="star-filled" size="16" color="#ffb400"></uni-icons>
              <text>{{spot.average_rating || 0}}</text>
            </view>
            <text class="spot-address">{{spot.spot_address}}</text>
          </view>
        </view>
      </scroll-view>
    </view>

    <!-- 非遗店铺推荐 -->
    <view class="section" v-if="shops.length > 0">
      <view class="section-header">
        <text class="section-title">非遗体验店</text>
        <text class="section-more" @click="navigateToShopList">查看更多 ></text>
      </view>
      <view class="shop-list">
        <view class="shop-item" v-for="(shop, index) in shops" :key="index" @click="navigateToShopDetail(shop.shop_id)">
          <image :src="getMainImage(shop.shop_id, 'shop')" mode="aspectFill" class="shop-image"></image>
          <view class="shop-detail">
            <text class="shop-name">{{shop.shop_name}}</text>
            <text class="shop-type">{{shop.experience_type}}</text>
            <text class="shop-price">{{formatPrice(shop.price_range)}}</text>
            <view class="shop-rating">
              <uni-icons type="star-filled" size="16" color="#ffb400"></uni-icons>
              <text>{{shop.average_rating || 0}}</text>
            </view>
          </view>
        </view>
      </view>
    </view>

    <!-- 美食文化展示 -->
    <view class="section" v-if="foods.length > 0">
      <view class="section-header">
        <text class="section-title">景德镇美食</text>
        <text class="section-more" @click="navigateToFoodList">查看更多 ></text>
      </view>
      <view class="food-card" @click="navigateToFoodDetail(foods[0].food_id)">
        <image :src="getMainImage(foods[0].food_id, 'food')" mode="aspectFill" class="food-image"></image>
        <view class="food-content">
          <text class="food-title">{{foods[0].food_name}}</text>
          <text class="food-desc">{{foods[0].food_description | truncate(50)}}</text>
        </view>
      </view>
    </view>

    <!-- 加载状态 -->
    <uni-load-more :status="loadingStatus" v-if="loading"></uni-load-more>
  </view>
</template>

<script>
import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'
import uniLoadMore from '@dcloudio/uni-ui/lib/uni-load-more/uni-load-more.vue'
import { scenicSpotApi, shopApi, foodApi, searchApi, imageApi } from '@/api'

export default {
  components: {
    uniIcons,
    uniLoadMore
  },
  filters: {
    truncate(value, length) {
      if (!value) return ''
      if (value.length > length) {
        return value.substring(0, length) + '...'
      }
      return value
    }
  },
  data() {
    return {
      banners: [],
      spots: [],
      shops: [],
      foods: [],
      searchKeyword: '',
      loading: false,
      loadingStatus: 'loading',
      imageMap: {} // 缓存图片数据
    }
  },
  onLoad() {
    this.loadHomeData()
  },
  methods: {
    async loadHomeData() {
      try {
        this.loading = true
        this.loadingStatus = 'loading'
        
        // 并行加载所有数据
        await Promise.all([
          this.loadBanners(),
          this.loadSpots(),
          this.loadShops(),
          this.loadFoods()
        ])
        
        this.loadingStatus = 'more'
      } catch (error) {
        console.error('加载首页数据失败:', error)
        uni.showToast({
          title: '数据加载失败',
          icon: 'none'
        })
        this.loadingStatus = 'more'
      } finally {
        this.loading = false
      }
    },
    
    async loadBanners() {
      try {
        // 获取轮播图数据 - 这里假设从景点、店铺和美食中各取一个作为轮播图
        const [spotRes, shopRes, foodRes] = await Promise.all([
          scenicSpotApi.getAll({ page: 1, pageSize: 1 }),
          shopApi.getAll({ page: 1, pageSize: 1 }),
          foodApi.getAll({ page: 1, pageSize: 1 })
        ])
        
        this.banners = []
        
        if (spotRes.data.list.length > 0) {
          const spot = spotRes.data.list[0]
          const image = await this.getMainImage(spot.spot_id, 'spot')
          this.banners.push({
            image_url: image,
            type: 'spot',
            id: spot.spot_id
          })
        }
        
        if (shopRes.data.list.length > 0) {
          const shop = shopRes.data.list[0]
          const image = await this.getMainImage(shop.shop_id, 'shop')
          this.banners.push({
            image_url: image,
            type: 'shop',
            id: shop.shop_id
          })
        }
        
        if (foodRes.data.list.length > 0) {
          const food = foodRes.data.list[0]
          const image = await this.getMainImage(food.food_id, 'food')
          this.banners.push({
            image_url: image,
            type: 'food',
            id: food.food_id
          })
        }
      } catch (error) {
        console.error('加载轮播图失败:', error)
      }
    },
    
    async loadSpots() {
      try {
        const res = await scenicSpotApi.getAll({ page: 1, pageSize: 4, sort: 'rating_desc' })
        this.spots = res.data.list
        
        // 预加载图片
        await this.preloadImages(this.spots, 'spot_id', 'spot')
      } catch (error) {
        console.error('加载景点失败:', error)
      }
    },
    
    async loadShops() {
      try {
        const res = await shopApi.getAll({ page: 1, pageSize: 3, sort: 'rating_desc' })
        this.shops = res.data.list
        
        // 预加载图片
        await this.preloadImages(this.shops, 'shop_id', 'shop')
      } catch (error) {
        console.error('加载店铺失败:', error)
      }
    },
    
    async loadFoods() {
      try {
        const res = await foodApi.getAll({ page: 1, pageSize: 1 })
        this.foods = res.data.list
        
        // 预加载图片
        await this.preloadImages(this.foods, 'food_id', 'food')
      } catch (error) {
        console.error('加载美食失败:', error)
      }
    },
    
    // 获取主图
    async getMainImage(id, type) {
      const cacheKey = `${type}_${id}`
      
      // 先从缓存中获取
      if (this.imageMap[cacheKey]) {
        return this.imageMap[cacheKey]
      }
      
      try {
        const res = await imageApi.getByRelatedId(id, type)
        if (res.data && res.data.length > 0) {
          // 找到主图或第一张图
          const mainImage = res.data.find(img => img.is_main) || res.data[0]
          if (mainImage) {
            this.imageMap[cacheKey] = mainImage.image_url
            return mainImage.image_url
          }
        }
        return '/static/default-image.jpg' // 默认图片
      } catch (error) {
        console.error('获取图片失败:', error)
        return '/static/default-image.jpg' // 默认图片
      }
    },
    
    // 预加载图片
    async preloadImages(items, idField, type) {
      const promises = items.map(item => {
        return this.getMainImage(item[idField], type)
      })
      await Promise.all(promises)
    },
    
    formatPrice(priceRange) {
      if (!priceRange) return '价格待定'
      if (priceRange.includes('-')) {
        const [min, max] = priceRange.split('-')
        return `¥${min}-${max}`
      }
      return `¥${priceRange}`
    },
    
    onSearchInput(e) {
      this.searchKeyword = e.detail.value
    },
    
    async onSearchConfirm() {
      if (this.searchKeyword.trim()) {
        try {
          const res = await searchApi.search(this.searchKeyword.trim(), 'spot|shop|food')
          uni.navigateTo({
            url: `/pages/search/result?keyword=${encodeURIComponent(this.searchKeyword)}&data=${encodeURIComponent(JSON.stringify(res.data))}`
          })
        } catch (error) {
          uni.showToast({
            title: '搜索失败',
            icon: 'none'
          })
        }
      } else {
        uni.showToast({
          title: '请输入搜索内容',
          icon: 'none'
        })
      }
    },
    
    navigateToQA() {
      uni.switchTab({
        url: '/pages/qa/qa'
      })
    },
    
    navigateToMap() {
      uni.switchTab({
        url: '/pages/map/map'
      })
    },
    
    navigateToCommunity() {
      uni.switchTab({
        url: '/pages/community/community'
      })
    },
    
    navigateToFood() {
      uni.navigateTo({
        url: '/pages/food/list'
      })
    },
    
    navigateToSpotDetail(id) {
      uni.navigateTo({
        url: `/pages/spot/detail?id=${id}`
      })
    },
    
    navigateToShopDetail(id) {
      uni.navigateTo({
        url: `/pages/shop/detail?id=${id}`
      })
    },
    
    navigateToFoodDetail(id) {
      uni.navigateTo({
        url: `/pages/food/detail?id=${id}`
      })
    },
    
    navigateToSpotList() {
      uni.navigateTo({
        url: '/pages/spot/list'
      })
    },
    
    navigateToShopList() {
      uni.navigateTo({
        url: '/pages/shop/list'
      })
    },
    
    navigateToFoodList() {
      uni.navigateTo({
        url: '/pages/food/list'
      })
    },
    
    navigateToSearch() {
      uni.navigateTo({
        url: '/pages/search/search'
      })
    },
    
    navigateToDetail(item) {
      if (item.type === 'spot') {
        this.navigateToSpotDetail(item.id)
      } else if (item.type === 'shop') {
        this.navigateToShopDetail(item.id)
      } else {
        this.navigateToFoodDetail(item.id)
      }
    }
  }
}
</script>

